import { createHash } from 'node:crypto';
export const raw = true;
export default async function rstestWasmLoader(buffer) {
    const wasmModule = new WebAssembly.Module(buffer);
    const source = JSON.stringify(this.resourcePath);
    const contentHash = createHash('sha256').update(buffer).digest('hex');
    const names = WebAssembly.Module.exports(wasmModule).map((entry)=>entry.name);
    const bindings = names.map((name, i)=>`const __rstest_wasm_${i}__ = __rstest_wasm_ns__[${JSON.stringify(name)}];`).join('\n');
    const exportList = names.map((name, i)=>`__rstest_wasm_${i}__ as ${JSON.stringify(name)}`).join(', ');
    const importModules = [
        ...new Set(WebAssembly.Module.imports(wasmModule).map((entry)=>entry.module))
    ];
    const resolve = this.getResolve();
    const resolved = await Promise.all(importModules.map((module)=>resolve(this.context, module).then(()=>module, ()=>null)));
    const modules = resolved.filter((module)=>null !== module);
    const glueImports = modules.map((module, i)=>`import * as __rstest_wasm_glue_${i}__ from ${JSON.stringify(module)};`);
    const importObject = modules.map((module, i)=>`${JSON.stringify(module)}: __rstest_wasm_glue_${i}__`).join(', ');
    return [
        `// rstest:wasm-content ${contentHash}`,
        'import { readFileSync as __rstest_read_wasm__ } from "node:fs";',
        ...glueImports,
        `const { instance: __rstest_wasm_instance__ } = await WebAssembly.instantiate(__rstest_read_wasm__(${source}), { ${importObject} });`,
        'const __rstest_wasm_ns__ = __rstest_wasm_instance__.exports;',
        bindings,
        `export { ${exportList} };`,
        ''
    ].join('\n');
}
